#!/usr/bin/env python3
"""
Deploy a new test WXTZ token that YOU control and can mint freely.
Then update the .env to use this new token.
"""

import os
import sys
import json
from web3 import Web3
from dotenv import load_dotenv, set_key

load_dotenv()

RPC_URL = os.getenv("RPC_URL", "https://node.shadownet.etherlink.com")
PRIVATE_KEY = os.getenv("WALLET_PRIVATE_KEY")

# Simple ERC20 with public mint
TOKEN_BYTECODE = "0x608060405234801561001057600080fd5b506040516109ee3803806109ee83398101604081905261002f9161007c565b600361003b8382610198565b50600461004882826101  7565b610298565b005b6100f3610146366004610670565b6001600160a01b031660009081526020819052604090205490565b6100b66102a5565b61013661017736600461065  "

TOKEN_ABI = [
    {"inputs":[{"internalType":"string","name":"name_","type":"string"},{"internalType":"string","name":"symbol_","type":"string"}],"stateMutability":"nonpayable","type":"constructor"},
    {"inputs":[{"internalType":"uint256","name":"amount","type":"uint256"}],"name":"mint","outputs":[],"stateMutability":"nonpayable","type":"function"},
    {"inputs":[{"internalType":"address","name":"account","type":"address"}],"name":"balanceOf","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},
    {"inputs":[],"name":"decimals","outputs":[{"internalType":"uint8","name":"","type":"uint8"}],"stateMutability":"view","type":"function"},
    {"inputs":[{"internalType":"address","name":"spender","type":"address"},{"internalType":"uint256","name":"amount","type":"uint256"}],"name":"approve","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"nonpayable","type":"function"},
    {"inputs":[{"internalType":"address","name":"to","type":"address"},{"internalType":"uint256","name":"amount","type":"uint256"}],"name":"transfer","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"nonpayable","type":"function"}
]

def main():
    print("🏗️  Deploying Test WXTZ Token (that you can mint)...")
    
    w3 = Web3(Web3.HTTPProvider(RPC_URL))
    if not w3.is_connected():
        print("❌ Failed to connect")
        return 1
    
    account = w3.eth.account.from_key(PRIVATE_KEY)
    print(f"✅ Deployer: {account.address}")
    
    # Deploy simple ERC20
    print("\n📝 Deploying TestWXTZ contract...")
    nonce = w3.eth.get_transaction_count(account.address)
    
    # Constructor parameters: name, symbol
    from eth_abi import encode
    constructor_args = encode(['string', 'string'], ['Test Wrapped XTZ', 'TWXTZ'])
    
    deploy_tx = {
        'from': account.address,
        'data': TOKEN_BYTECODE + constructor_args.hex(),
        'nonce': nonce,
        'gas': 2000000,
        'gasPrice': int(w3.eth.gas_price * 1.2),
        'chainId': w3.eth.chain_id
    }
    
    signed = w3.eth.account.sign_transaction(deploy_tx, private_key=PRIVATE_KEY)
    tx_hash = w3.eth.send_raw_transaction(signed.raw_transaction)
    print(f"⏳ TX: {tx_hash.hex()}")
    receipt = w3.eth.wait_for_transaction_receipt(tx_hash, timeout=120)
    
    if receipt['status'] != 1:
        print("❌ Deployment failed")
        return 1
    
    token_address = receipt['contractAddress']
    print(f"✅ TestWXTZ deployed at: {token_address}")
    
    # Mint 1000 tokens
    print(f"\n🪙 Minting 1000 TWXTZ to your wallet...")
    token = w3.eth.contract(address=token_address, abi=TOKEN_ABI)
    
    nonce += 1
    mint_tx = token.functions.mint(w3.to_wei(1000, 'ether')).build_transaction({
        'from': account.address,
        'nonce': nonce,
        'gas': 500000,
        'gasPrice': int(w3.eth.gas_price * 1.2),
        'chainId': w3.eth.chain_id
    })
    
    signed = w3.eth.account.sign_transaction(mint_tx, private_key=PRIVATE_KEY)
    tx_hash = w3.eth.send_raw_transaction(signed.raw_transaction)
    receipt = w3.eth.wait_for_transaction_receipt(tx_hash, timeout=120)
    
    if receipt['status'] == 1:
        balance = token.functions.balanceOf(account.address).call()
        print(f"✅ Minted! Balance: {w3.from_wei(balance, 'ether')} TWXTZ")
    else:
        print("❌ Mint failed")
        return 1
    
    # Update .env
    print(f"\n📝 Updating .env file...")
    env_path = "/Users/adarsh/Documents/alpha-consumer/.env"
    set_key(env_path, "WXTZ_ADDRESS", token_address)
    print(f"   WXTZ_ADDRESS={token_address}")
    print("\n✅ Setup complete!")
    print("\n💡 Next steps:")
    print("   1. Run: python check_and_add_liquidity.py")
    print("   2. Then: ./start_all.sh")
    
    return 0

if __name__ == "__main__":
    sys.exit(main())
